  "about.eyebrow": "Luminous StockHaven గురించి",
  "about.pageTitle": "Luminous StockHaven — మా గురించి",
  "about.founderHeading": "📖 వ్యవస్థాపకురాలి గురించి",
  "about.founder.p1": "హలో, నేను కాన్సెప్షియోన్, Luminous StockHaven వ్యవస్థాపకురాలిని.",
  "about.founder.p2": "నేను పెద్ద టెక్ కంపెనీ నుండి రాలేదు, నేను కార్పొరేట్ కార్యాలయంలో కూర్చోను. నేను మీలాగే ఒక చిన్న రిటైల్ యజమానిని. పుస్తకాలు మరియు పుస్తక ప్రేమికుల కోసం చేతితో తయారు చేసిన ఉపకరణాలలో ప్రత్యేకత కలిగిన ఐదు ఇ-కామర్స్ దుకాణాలను నేను నిర్వహిస్తాను.\nచాలా మంది స్వతంత్ర రిటైలర్ల మాదిరిగానే, అనేక ప్రదేశాలలో ఇన్వెంటరీని నిర్వహించడానికి, ప్రచురణకర్తల ISBNలను నా స్వంత చేతితో తయారు చేసిన SKUలతో పాటు ట్రాక్ చేయడానికి, మరియు ఇబ్బందికరమైన స్ప్రెడ్‌షీట్‌లతో సరఫరాదారు ఆర్డర్‌లను నిర్వహించడానికి ప్రయత్నిస్తున్నప్పుడు నేను ఒక విచ్ఛిన్న స్థితికి చేరుకున్నాను. నాకు సహాయపడే యాప్ కోసం వెతికినప్పుడు, నేను ఆరు వేర్వేరు ఎంపికలను ప్రయత్నించాను. ప్రతి ఒక్కటీ పూర్తిగా అసంపూర్ణంగా, నమ్మశక్యం కానంత గందరగోళంగా, లేదా దోపిడీగా ఉండేది — ప్రాథమిక సాధనాల కోసం నెలకు వందల డాలర్లు వసూలు చేసేవి.",
  "about.founder.p3": "స్వతంత్ర సృష్టికర్తలను పిండే పరిశ్రమతో విసుగు చెంది, నా స్వంత పరిష్కారాన్ని నిర్మించాలని నిర్ణయించుకున్నాను. నా స్వంత వ్యాపారాలను శుభ్రంగా, సమర్థవంతంగా మరియు పూర్తి మనశ్శాంతితో నడపడానికి అవసరం నుండి Luminous StockHavenని నిర్మించాను.",
  "about.founder.p4": "ప్రతి చిన్న వ్యాపార యజమాని తమ ఆదాయాన్ని ప్రమాదంలో పడేయకుండా నిజంగా పనిచేసే సాధనాలకు అర్హుడనే కారణంతో, ఈ ప్లాట్‌ఫారమ్‌ను నిజాయితీగా, సరసమైన ధరకు ప్రజలకు తెరవాలని నిర్ణయించుకున్నాను. మేము స్వతంత్రంగా యాజమాన్యంలో ఉన్నాము, మా సంఘాన్ని తీవ్రంగా రక్షిస్తాము, మరియు ఒక రిటైలర్ ద్వారా, రిటైలర్ల కోసం నిర్మించబడ్డాము.",
  "notice.ariaLabel": "ట్రేడ్‌మార్క్ మరియు కాపీరైట్ నోటీసు",
  "notice.heading": "🛡️ రిటైలర్ల కోసం నిర్మించబడింది, కార్పొరేట్ రాబందులకు అమూల్యం",
  "notice.intro": "నేను 5 దుకాణాలు నడుపుతున్నాను మరియు వందల డాలర్ల గందరగోళ సాఫ్ట్‌వేర్‌తో మోసపోవడం విసుగు తెప్పించినందున నేను ఈ యాప్‌ను నిర్మించాను. స్వతంత్ర కళాకారులు, చేతివృత్తులవారు, పుస్తక విక్రేతలు మరియు స్థానిక దుకాణాలను రక్షించడానికి ఈ యాప్ నిర్మించబడింది.",
  "notice.legalHeading": "పోటీదారులు & అనుకరించేవారికి చట్టపరమైన నోటీసు:",
  "notice.legalBody": "మేము మార్కెట్‌ను చురుకుగా పర్యవేక్షిస్తాము. మా ప్లాట్‌ఫారమ్‌ను స్క్రాప్ చేయడానికి, మా యాజమాన్య వర్క్‌ఫ్లోలను క్లోన్ చేయడానికి, లేదా మా మేధో సంపత్తిని ఉల్లంఘించడానికి చేసే ఏ ప్రయత్నమైనా తక్షణ, దూకుడు చట్టపరమైన చర్యను ఎదుర్కొంటుంది.",
  "notice.acquisitionHeading": "స్వాధీన సంస్థలు & బ్రోకర్లకు:",
  "notice.acquisitionBody": "నాకు ఇమెయిల్ పంపవద్దు. నాకు సందేశం పంపవద్దు. నాకు 'వ్యూహాత్మక నిష్క్రమణ'ను ప్రతిపాదించవద్దు. మీరు వేలు, లక్షలు, కోట్లు లేదా ట్రిలియన్లు అందించవచ్చు — సమాధానం కాదు. నా తోటి వ్యాపారుల కోసం ధరలను పెంచడానికి మాత్రమే మీరు ఈ యాప్‌ను కొనరు. కోరని ప్రతి స్వాధీన ఇమెయిల్ వెంటనే స్పామ్‌గా గుర్తించబడుతుంది, మరియు మీ డొమైన్ మా ప్లాట్‌ఫారమ్ నుండి శాశ్వతంగా నిరోధించబడుతుంది. మీ శ్రమను ఆదా చేసుకోండి.",
  "footer.trademarkLine": "అనధికార నకలు, క్లోనింగ్ లేదా డేటా స్క్రాపింగ్ ఖచ్చితంగా నిషేధించబడింది.",
