  "welcome.noTrialNote": "ఈ స్క్రీన్‌ను తెరవడం వల్ల ఏదీ ప్రారంభం కాదు. ట్రయల్ ప్రారంభం కాదు, కార్డ్‌పై ఛార్జీ పడదు — మీరు ప్లాన్‌ను ఎంచుకుని నిర్ధారించినప్పుడు మాత్రమే ఏడు రోజుల ట్రయల్ ప్రారంభమవుతుంది. రెండు వెబ్‌సైట్ ప్లాన్‌లలోనూ మొబైల్ సహాయకుడు చేర్చబడింది, కాబట్టి వాటికి అదనంగా నెలవారీ మొబైల్ రుసుమును మీరు ఎప్పుడూ చెల్లించరు.",
