  "thankYou.unverified.default": "మీ కొనుగోలు ఇంకా ధృవీకరించబడలేదు. మేము తనిఖీ చేస్తూనే ఉంటాము — మరొక చెక్అవుట్‌ను ప్రారంభించవద్దు.",
