  "valuation.noRetailPrice": "రిటైల్ ధర లేదు",
  "valuation.footnote": "ఖర్చు విలువ ప్రతి ఉత్పత్తి యొక్క ప్రస్తుత యూనిట్ ఖర్చును ఉపయోగిస్తుంది, కాబట్టి కొత్త ధర వద్ద స్వీకరించడం మొత్తం షెల్ఫ్‌ను తిరిగి విలువ చేస్తుంది. ఉంచిన యూనిట్లు ఇక్కడ ఇంకా లెక్కించబడతాయి — అవి చేతిలో ఉన్నాయి, కేవలం ఒక ఆర్డర్‌కు వాగ్దానం చేయబడ్డాయి. తప్పిపోయిన డబ్బు ఎప్పుడూ సున్నాగా పరిగణించబడదు; సంఖ్య తెలిసే వరకు ఒక ఫీల్డ్‌ను ఖాళీగా ఉంచండి.",
