  "print.supplierBlockedDesc": "సరఫరాదారు పత్రాలు Business ప్లాన్‌తో వెళ్తాయి — సరఫరాదారులు, కొనుగోలు మరియు కొనుగోలు ఆర్డర్‌లు. మీ వద్ద ఇప్పుడు ఉన్న ప్రతిదీ పనిచేస్తూనే ఉంటుంది.",
