  "print.chooseStyleHint": "ఒక శైలిని ఎంచుకోండి, తరువాత జాబితా నుండి ఉత్పత్తులను ఎంచుకోండి. ప్రివ్యూ ప్రింటర్ నుండి ఖచ్చితంగా ఏమి వస్తుందో చూపుతుంది.",
  "print.howToReach": "మీ ప్రింటర్‌ను ఎలా చేరుకోవాలి",
  "print.howIntro": "ఈ యాప్ మీ వద్ద ఇప్పటికే ఉన్న ప్రింటర్‌లకు కనెక్ట్ అవుతుంది — ఇది స్వయంగా ప్రింటర్ కాదు. దానిని చేరుకోవడానికి నాలుగు మార్గాలు ఉన్నాయి, మరియు లేబుల్‌లు వాటిలో దేనిద్వారానైనా రెండు ప్లాన్‌లలో ప్రింట్ అవుతాయి. ప్యాకింగ్ స్లిప్‌లు, కొనుగోలు ఆర్డర్‌లు, సరఫరాదారు పత్రాలు మరియు నివేదికలు కనెక్షన్ ఏదైనా సరే Business-మాత్రమే.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "ఈ పేజీ నుండి, డెస్క్‌టాప్ Chrome లేదా Edge లో మరియు Android Chrome లో: మీ లేబుల్ ప్రింటర్‌ను ఎంచుకోండి మరియు లేబుల్‌లు నేరుగా దాని వద్దకు వెళ్తాయి. ఇది iOS Safari లో పనిచేయదు — iPhone లో, Bluetooth ప్రింటింగ్ బదులుగా మొబైల్ యాప్‌తో వస్తుంది. కేవలం Zebra ZPL లేదా Brother యొక్క స్వంత భాషను మాత్రమే మాట్లాడే ప్రింటర్ ఈ పేజీ పంపే లేబుల్‌లను అర్థం చేసుకోదు; అది పనిచేస్తుందని చెప్పడానికి ముందు నిజమైన ప్రింటర్‌లకు వ్యతిరేకంగా తనిఖీ చేయబడుతుంది.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "ప్రింటర్‌ను మీ దుకాణం యొక్క Wi-Fi లో ఇన్‌స్టాల్ చేయండి, తరువాత ప్రింట్ బటన్‌ను ఉపయోగించండి — ఇది దుకాణ నెట్‌వర్క్ ద్వారా ఈ కంప్యూటర్‌లో ఇన్‌స్టాల్ చేసిన ప్రింటర్ ద్వారా ప్రింట్ చేస్తుంది. iPhone లో, AirPrint అంతర్నిర్మితంగా ఉంటుంది: అదే Wi-Fi లో ఉన్న AirPrint ప్రింటర్ ప్రింట్ షీట్‌లో కనిపిస్తుంది, త్రాడు మరియు యాప్ అవసరం లేదు, మరియు యాప్‌కు AirPrint-నిర్దిష్ట కోడ్ అవసరం లేదు. ప్రింటర్ AirPrint కు మద్దతు ఇవ్వాలి (చాలా కొత్తవి ఇస్తాయి) మరియు ఫోన్ మరియు ప్రింటర్ అదే Wi-Fi లో ఉండాలి.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "ప్రింటర్‌ను Ethernet త్రాడుతో మీ దుకాణ నెట్‌వర్క్‌కు వైర్ చేయండి, దానిని కంప్యూటర్‌లో ఇన్‌స్టాల్ చేయండి, మరియు ప్రింట్ బటన్ ద్వారా ప్రింట్ చేయండి. Ethernet అనేది డెస్క్‌టాప్ మరియు కంప్యూటర్ మార్గం — iPhone లు Ethernet త్రాడులను ఉపయోగించవు.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "ప్రింటర్‌ను దాని త్రాడుతో కంప్యూటర్‌కు ప్లగ్ చేసి ప్రింట్ బటన్‌ను ఉపయోగించండి — ఇది అక్కడ ఇన్‌స్టాల్ చేసిన ప్రింటర్ ద్వారా ప్రింట్ చేస్తుంది. USB OTG కేబుల్‌తో Android ఫోన్‌లో, పైన ఉన్న USB బటన్ నేరుగా ప్రింటర్‌తో మాట్లాడుతుంది. iPhone లు USB ద్వారా నేరుగా ప్రింట్ చేయలేవు — అక్కడ WebUSB లేదు — కాబట్టి Wi-Fi / AirPrint ను, లేదా మొబైల్ యాప్ నుండి Bluetooth ను ఉపయోగించండి.",
  "print.howCordsLead": "త్రాడులు ఇంకా iPhone లకు సేవ చేస్తాయి, ఒక అడుగు దూరంగా.",
  "print.howCordsBody": "దుకాణ కంప్యూటర్‌కు ప్లగ్ చేసిన USB ప్రింటర్, లేదా నెట్‌వర్క్‌కు వైర్ చేసిన Ethernet ప్రింటర్, దుకాణ Wi-Fi ద్వారా మీ iPhone లో కనిపిస్తుంది (AirPrint / భాగస్వామ్య ప్రింటర్) — త్రాడులు ప్రింటర్‌ను నెట్‌వర్క్‌పై దృఢంగా ఉంచుతాయి, మరియు ఫోన్ దానిని వైర్‌లెస్‌గా చేరుకుంటుంది.",
  "print.howOfflineLead": "ఇంటర్నెట్ పడిపోతే,",
  "print.howOfflineBody": "ఈ పేజీలో ఇప్పటికే ఉన్న లేబుల్‌లు మరియు పత్రాలు ఇంకా ప్రింట్ అవుతాయి — ప్రింట్ బటన్, లేబుల్‌ల PDF, Bluetooth మరియు USB కు కనెక్షన్ అవసరం లేదు. ఇంటర్నెట్ అవసరమయ్యేది మొదట పేజీని మరియు దాని ఉత్పత్తులను లోడ్ చేయడం. పూర్తి ఆఫ్‌లైన్ మోడ్ (అస్సలు కనెక్షన్ లేకుండా యాప్‌లో పనిచేయడం) అనేది వేరు, పెద్ద నిర్మాణం మరియు ఇక్కడ క్లెయిమ్ చేయబడలేదు.",
