  "settings.logout": "లాగ్ అవుట్",
  "settings.pastDue.body": "మీ చివరి చెల్లింపు జరగలేదు. విఫలమైన చెల్లింపు నుండి 14 రోజుల పాటు, మీరు దానిని సరిచేసే వరకు పూర్తి వినియోగాన్ని కొనసాగిస్తారు. అది సరిచేయకపోతే, సభ్యత్వం రద్దు అవుతుంది, వర్క్‌స్పేస్ 15 రోజుల పాటు వీక్షణ-మాత్రమే అవుతుంది, ఆపై ఖాతా మరియు దాని సమాచారం అంతా తొలగించబడుతుంది. తొలగింపుకు ముందు ఎప్పుడైనా చెల్లించడం వల్ల అన్నీ తిరిగి వస్తాయి. ఏమి చేయాలో ఖచ్చితంగా తెలియకపోతే, theluminousbookshop@outlook.com వద్ద మద్దతును సంప్రదించండి.",
  "settings.pastDue.fixBy": "పూర్తి వినియోగం {date} వరకు కొనసాగుతుంది.",
