  "workforce.inbox.help": "మీ బృందం కోసం క్లాక్ ఈవెంట్‌లు, సెలవు సమాధానాలు, పనులు, పే స్టబ్‌లు మరియు షెడ్యూల్ మార్పులు, సరికొత్తవి ముందు.",
