  "training.team.daysHint": "గడువు లేకపోవడానికి ఖాళీగా ఉంచండి.",
  "training.team.deadlineFailed": "గడువును సేవ్ చేయలేకపోయాం.",
  "training.team.deadlineSave": "గడువును సేవ్ చేయండి",
  "training.team.deadlineSaved": "గడువు సేవ్ చేయబడింది.",
  "training.team.help": "ఎవరు ఏమి పూర్తి చేశారో చూడండి, పాఠాలను కేటాయించండి, గడువులను సెట్ చేయండి, మరియు శిక్షణ గడువు దాటినప్పుడు హెచ్చరికను పంపండి.",
