  "auth.sameEmailNotice": "Google Play లేదా App Store నుండి మా యాప్ ఇప్పటికే ఉందా? ఇక్కడ అదే ఇమెయిల్‌ను ఉపయోగించండి — మీరు యాప్‌లోకి సైన్ ఇన్ చేసేది — కాబట్టి మీ దుకాణం మరియు మీ ఇన్వెంటరీ మీతో వస్తాయి. వేరే ఇమెయిల్ పూర్తిగా కొత్త, ఖాళీ స్టోర్‌ఫ్రంట్‌ను ప్రారంభిస్తుంది.",
