  "recovery.changeIntro": "మీరు లోపలికి వచ్చారు — ఒక దశ కోసం మాత్రమే: మీ ఖాతా కోసం కొత్త ఇమెయిల్‌ను ఎంచుకోండి. మీ దుకాణం, మీ ఇన్వెంటరీ మరియు మీ బృంద ప్రాప్యత అంతా దానితో కదులుతాయి.",
