  "print.senderAddressLabel": "మీ చిరునామా (పంపినవారు)",
  "print.shippingNote": "ఆర్డర్‌లో పంపవలసిన చిరునామా ఉంటే, అది ఆర్డర్ నుండి నింపబడుతుంది. మీరు ఇక్కడ టైప్ చేసేది ఒక్కసారి ముద్రించబడుతుంది మరియు ఎప్పటికీ తిరిగి సేవ్ చేయబడదు.",
  "print.carrier.title": "మీ క్యారియర్ లేబుల్",
  "print.carrier.desc": "పోస్టేజీని క్యారియర్ నుండి కొనండి, మీరు ఈ రోజు చేసినట్లుగా — ఈ యాప్ ఎప్పుడూ పోస్టేజీని అమ్మదు, కాబట్టి మీరు చెల్లించే ధర ఎల్లప్పుడూ క్యారియర్ స్వంత ధరే. లేబుల్ ఫైల్‌ను ఇక్కడ సేవ్ చేయండి మరియు అది ఈ ఆర్డర్‌పై శాశ్వతంగా ఉంటుంది: మీ రికార్డు, ఏదైనా జరిగితే చేతిలో ఉంటుంది.",
  "print.carrier.none": "ఈ ఆర్డర్ కోసం ఇంకా క్యారియర్ లేబుల్ ఏదీ సేవ్ చేయబడలేదు.",
  "print.carrier.upload": "లేబుల్ ఫైల్‌ను అప్‌లోడ్ చేయండి",
