  "print.carrier.tooLarge": "ఆ ఫైల్ చాలా పెద్దది — లేబుల్ ఫైల్ 25 MB కంటే తక్కువ ఉండాలి.",
  "print.carrier.badType": "ఆ ఫైల్ పని చేయదు — PDF, PNG లేదా JPG లేబుల్‌ను ఎంచుకోండి.",
  "print.carrier.failed": "లేబుల్ సేవ్ చేయబడలేదు. ఏమీ మారలేదు — మళ్లీ ప్రయత్నించండి.",
  "print.carrier.removeConfirm": "ఈ ఆర్డర్ కోసం సేవ్ చేసిన క్యారియర్ లేబుల్‌ను తీసివేయాలా? ఫైల్ యాప్ నుండి తొలగించబడుతుంది.",
  "print.carrier.pdfHint": "ఈ లేబుల్ ఒక PDF. ఇది దాని నిజమైన పరిమాణంలో తెరుచుకుంటుంది — వీక్షకుడి నుండి ముద్రించండి మరియు అది సరిగ్గా 4×6 గా బయటకు వస్తుంది.",
  "print.carrier.pickOrderFirst": "పైన ఒక ఆర్డర్‌ను ఎంచుకోండి, ఆపై దాని క్యారియర్ లేబుల్‌ను ఇక్కడ సేవ్ చేయండి.",
  'print.carrier.pickFirstTap': "ముందు పైన ఒక ఆర్డర్‌ను ఎంచుకోండి — ఆ తర్వాత ఈ బటన్ క్యారియర్ లేబుల్‌ను ఆ ఆర్డర్‌లో సేవ్ చేస్తుంది.",
  "print.style.title": "పత్ర శైలి",
  "print.style.desc": "మీ పత్రాలను మీవిగా చేసుకోండి. ఈ ఎంపికలు మీ ఇన్‌వాయిస్, రసీదు, ప్యాకింగ్ స్లిప్, రిటర్న్ పత్రాలు, ఉత్పత్తి షీట్‌లు, లెక్కింపు షీట్‌లు మరియు పిక్ జాబితాలను అలంకరిస్తాయి — మరియు మీ వ్యాపారం కోసం గుర్తుంచుకోబడతాయి.",
  "print.style.logoLabel": "మీ లోగో",
  "print.style.logoOn": "మీ లోగో మీ పత్రాల పైన ముద్రించబడుతుంది.",
  "print.style.logoOff": "ఇంకా లోగో లేదు. సెట్టింగ్‌లలో ఒకదాన్ని జోడించండి మరియు అది మీ పత్రాల పైన ముద్రించబడుతుంది.",
  "print.style.color": "రంగులో ముద్రించండి",
  "print.style.colorHint": "ఆన్: మీ లోగో, చిత్రాలు మరియు ఫ్రేమ్ రంగులో ముద్రించబడతాయి. ఆఫ్: ప్రతిదీ శుభ్రమైన నలుపు-తెలుపులో ముద్రించబడుతుంది, సిరా ఆదా అవుతుంది.",
  "print.style.font": "పత్ర ఫాంట్",
