  "print.style.saveFailed": "శైలిని సేవ్ చేయలేకపోయాము. ఏమీ మారలేదు — మళ్లీ ప్రయత్నించండి.",
  "print.style.imageWidth": "చిత్రం వెడల్పు",
  "print.style.imageLength": "చిత్రం పొడవు",
  "print.style.imageSizeHint": "వెడల్పు అంటే చిత్రం ఆక్రమించే పేజీ వెడల్పు వాటా; పొడవు అంటే ముద్రించగల గరిష్ఠ ఎత్తు. సాధారణ పరిమాణం కోసం పెట్టెను ఖాళీగా వదిలేయండి.",
  "print.printedAt": "{date} న {time} కు ముద్రించబడింది",
  "print.style.previewText": "వేగవంతమైన గోధుమ నక్క సోమరి కుక్కపై దూకుతుంది. 1234567890",
  "training.lessons.owner-shipping-labels.step1": "ప్రింట్ సెంటర్‌లో రెండు ప్లాన్‌లలోనూ షిప్పింగ్ లేబుల్ శైలి ఉంది: కస్టమర్ ఆర్డర్‌ను ఎంచుకుని, కొనుగోలుదారు పేరు మరియు చిరునామాతో, పంపినవారిగా మీ వ్యాపారంతో 4×6 లేబుల్‌ను ముద్రించండి.",
  "training.lessons.owner-shipping-labels.step2": "ఈ లేబుల్ ప్రతి కస్టమర్ పత్రంలాగే వైట్-లేబుల్: దానిపై మీ వ్యాపార పేరు మాత్రమే ఉంటుంది — ఈ యాప్ పేరు ఎప్పుడూ ఉండదు — కాబట్టి మీ దుకాణం నుండి వచ్చిన పార్శిల్ మీ దుకాణం నుండే వచ్చినట్లు కనిపిస్తుంది.",
  "training.lessons.owner-shipping-labels.step3": "వినియోగదారుడి చిరునామా వారి చివరి ఆర్డర్ తర్వాత 90 రోజుల పాటు వారి ఆర్డర్‌లతో పాటు ఉంచబడుతుంది, మరియు లేబుల్ ఉన్నప్పుడు ఆర్డర్ నిల్వ చేసిన చిరునామా నుండి ప్రారంభమవుతుంది; ఒకేసారి లేబుల్ కోసం ముద్రణ సమయంలో టైప్ చేసిన చిరునామా తిరిగి సేవ్ చేయబడదు. పేరు ఇప్పటికీ ఆర్డర్ నుండి నిండుతుంది, కాబట్టి లేబుల్ పత్రాలతో సరిపోతుంది.",
  "training.lessons.owner-shipping-labels.step4": "ఈ లేబుల్ ప్రతి లేబుల్‌లాగే అదే నాలుగు కనెక్షన్‌ల ద్వారా ముద్రించబడుతుంది — బ్లూటూత్, వై-ఫై, ఈథర్‌నెట్ మరియు USB — మరియు 4×6 థర్మల్ ప్రింటర్ దాని ప్రామాణిక పరిమాణం.",
  "training.lessons.owner-shipping-labels.step5": "బదులుగా పోస్టేజీని క్యారియర్ నుండి కొన్నారా? ఈ విభాగంలోనే మీరు క్యారియర్ లేబుల్ ఫైల్‌ను — PDF, PNG లేదా JPG — అప్‌లోడ్ చేయవచ్చు మరియు అది ఆర్డర్‌పై శాశ్వతంగా సేవ్ చేయబడి ఉంటుంది: మీ రికార్డు, ఏదైనా జరిగితే చేతిలో ఉంటుంది. ఇది దాని నిజమైన 4×6 పరిమాణంలో ముద్రించబడుతుంది. యాప్ ఎప్పుడూ పోస్టేజీని అమ్మదు, కాబట్టి క్యారియర్ ధరే ఏకైక ధర — మరియు ఎల్లప్పుడూ సరైన ధర.",
  "training.lessons.owner-shipping-labels.title": "కస్టమర్ ఆర్డర్‌ల కోసం షిప్పింగ్ లేబుళ్లు",
  "training.lessons.print-shipping-label.step1": "ఆర్డర్ పంపడానికి సిద్ధంగా ఉన్నప్పుడు, ప్రింట్ సెంటర్‌ను తెరిచి, షిప్పింగ్ లేబుల్ శైలిని ఎంచుకుని, ఆపై కస్టమర్ ఆర్డర్‌ను ఎంచుకోండి. కొనుగోలుదారు పేరు ఆర్డర్ నుండి నింపబడుతుంది.",
  "training.lessons.print-shipping-label.step2": "పార్శిల్ వెళ్లే చిరునామాను తనిఖీ చేయండి. ఆర్డర్ వినియోగదారుడి చిరునామాను కలిగి ఉన్నప్పుడు — వారి చివరి ఆర్డర్ తర్వాత 90 రోజులు ఉంచబడుతుంది — అది మీ కోసం నిండుతుంది; ముద్రణ సమయంలో మీరు టైప్ చేసిన చిరునామా తిరిగి సేవ్ చేయబడదు, కాబట్టి ముద్రించే ముందు పోస్ట్‌కోడ్ మరియు చివరి లైన్‌ను జాగ్రత్తగా తనిఖీ చేయండి.",
  "training.lessons.print-shipping-label.step3": "మీ వ్యాపార పేరు పంపినవారిగా పైన ముద్రించబడుతుంది. మీ చిరునామా కూడా లేబుల్‌పై కావాలంటే, దాన్ని పంపినవారి చిరునామా పెట్టెలో టైప్ చేయండి; కనిపించకూడదనుకుంటే ఖాళీగా వదిలేయండి.",
  "training.lessons.print-shipping-label.step4": "4×6 లేబుల్‌పై ముద్రించండి — థర్మల్ లేబుల్ ప్రింటర్ సాధారణ ఎంపిక — లేదా బ్రౌజర్ ప్రింట్ బటన్‌తో ఏ ప్రింటర్‌పైనైనా. లేబుల్‌ను అంచు మీద మడత పడకుండా పార్శిల్‌పై చదునుగా అతికించండి.",
  "training.lessons.print-shipping-label.step5": "పోస్టేజీ క్యారియర్ నుండి కొనబడి ఉంటే, బదులుగా వారి లేబుల్ ఫైల్‌ను ఆర్డర్‌పై సేవ్ చేయండి: మీ క్యారియర్ లేబుల్ విభాగంలో క్యారియర్ ఇచ్చిన PDF, PNG లేదా JPGని అప్‌లోడ్ చేయండి. ఇది మీ రికార్డుగా ఆర్డర్‌పై ఉంటుంది మరియు దాని నిజమైన 4×6 పరిమాణంలో ముద్రించబడుతుంది — మరియు మీరు దానిని ఉపయోగించాలనుకున్నప్పుడు యాప్ స్వంత చిరునామా లేబుల్ ఎల్లప్పుడూ అక్కడ ఉంటుంది.",
  "training.lessons.print-shipping-label.title": "షిప్పింగ్ లేబుల్ ముద్రించండి",
