  "pos.toast.help": "Toast, Toast భాగస్వామ్య కార్యక్రమం ద్వారా కనెక్ట్ అవుతుంది. మీ రెస్టారెంట్ భాగస్వామ్య ఆధారాలు సిద్ధమైనప్పుడు, వాటిని ఇక్కడ అతికించండి మరియు ప్రతి Toast అమ్మకం దాని అంశాలను తానే ఇక్కడ స్టాక్ నుండి తీస్తుంది.",
