  "pos.toast.clientIdPlaceholder": "మీ Toast భాగస్వామ్య ఆధారాల నుండి క్లయింట్ ID",
  "pos.toast.clientSecretPlaceholder": "మీ Toast భాగస్వామ్య ఆధారాల నుండి క్లయింట్ రహస్యం",
