  "profile.title": "మీ ప్రొఫైల్ ఫోటో",
  "profile.ownerDesc": "మీ ఫోటో మరియు మీ బృందం మిమ్మల్ని గుర్తించే పేరు. మీ స్వంత ఫోటో వెంటనే కనిపిస్తుంది — ఆమోదం అవసరం లేదు.",
  "profile.memberDesc": "యజమాని ఆమోదించిన తర్వాత మీ ఫోటో మీ పేరు పక్కన కనిపిస్తుంది. అప్పటి వరకు, మీ పేరులోని మొదటి అక్షరాలు మాత్రమే కనిపిస్తాయి.",
