  "profile.change": "ఫోటోను మార్చండి",
  "profile.declinedFirst": "మీ ఫోటో ఆమోదించబడలేదు. దయచేసి మరో ఫోటోను ఎంచుకోండి.",
  "profile.declinedChange": "మీ ఫోటో ఆమోదించబడలేదు — కానీ మీ మరో ఫోటో ఇంకా ఉంది. దాన్ని మార్చాలనుకుంటే, మరో ఫోటోను ప్రయత్నించండి.",
