  "profile.toastFailed": "అది పని చేయలేదు — దయచేసి మళ్లీ ప్రయత్నించండి.",
  "profile.nameLabel": "మీ పేరు",
  "profile.nameHint": "ఈ పేరు ప్రతిచోటా యజమాని అనే పదాన్ని భర్తీ చేస్తుంది — మీ ఫోటో పక్కన, సందేశాలలో మరియు మీ బృందం తెరలపై. ఖాళీగా వదిలితే మీరు యజమాని అనే పిలువబడతారు.",
