  "profile.nameCleared": "మీ పేరు తుడిచివేయబడింది — మీరు మళ్లీ యజమాని అని పిలువబడతారు.",
  "profile.approvalsTitle": "మీ ఆమోదం కోసం వేచి ఉన్న ఫోటోలు",
