  "profile.approvedToast": "ఫోటో ఆమోదించబడింది — ఇప్పుడు అది వారి పేరు పక్కన కనిపిస్తుంది.",
  "profile.declinedToast": "ఫోటో ఆమోదించబడలేదు — వారిని మరో ఫోటోను ఎంచుకోమని అడుగుతారు.",
  "plansLib.includes.profilePhotos": "మీ మొత్తం బృందం కోసం ప్రొఫైల్ ఫోటోలు, యజమాని ఆమోదించినవి",
  "apiErrors.notFound.photoFound": "ఫోటో కనుగొనబడలేదు.",
  "apiErrors.profileOwnerNameOnly": "వ్యాపార యజమాని మాత్రమే యజమాని పేరును సెట్ చేయగలరు.",
  "apiErrors.profilePhotosApproveOwnerOnly": "వ్యాపార యజమాని మాత్రమే బృంద ఫోటోలను ఆమోదించగలరు.",
  "apiErrors.profilePhotosNoneWaiting": "ఆ బృంద సభ్యుడికి ఆమోదం కోసం వేచి ఉన్న ఫోటో ఏదీ లేదు.",
  "apiErrors.profileOwnerNameTooLong": "మీ పేరును 80 అక్షరాలు లేదా అంతకంటే తక్కువగా ఉంచండి.",
  "training.lessons.your-profile-photo.title": "మీ ప్రొఫైల్ ఫోటో",
  "training.lessons.your-profile-photo.step1": "మీ ఫోటో యాప్ పైభాగంలో మీ పేరు పక్కన, సిబ్బంది పేజీలో మరియు మీ సందేశాల పక్కన కనిపిస్తుంది — యజమాని దాన్ని ఆమోదించిన తర్వాత. అప్పటి వరకు, మీ పేరులోని మొదటి అక్షరాలు మాత్రమే కనిపిస్తాయి.",
  "training.lessons.your-profile-photo.step2": "సెట్టింగ్‌లను తెరిచి మీ ప్రొఫైల్ ఫోటోను కనుగొనండి. మీ స్వంత ఫోటోను ఎంచుకుని పంపండి. అది ఆమోదం కోసం యజమాని వద్దకు వెళ్తుంది — వేచి ఉన్నప్పుడు అది ఎక్కడా కనిపించదు.",
  "training.lessons.your-profile-photo.step3": "యజమాని దాన్ని ఆమోదించినప్పుడు, మీ గంట మోగుతుంది మరియు మీ ఫోటో కనిపించడం ప్రారంభమవుతుంది. అది ఆమోదించబడకపోతే, వేరే ఫోటోను ఎంచుకుని దాన్ని పంపండి.",
  "training.lessons.your-profile-photo.step4": "మీ ఫోటోను మార్చడం కూడా అదే విధంగా పని చేస్తుంది: కొత్తది ఆమోదం కోసం వేచి ఉంటుంది, మరియు కొత్తది ఆమోదించబడే వరకు మీ ప్రస్తుత ఫోటో అలాగే ఉంటుంది. మార్పు ఆమోదించబడకపోతే, మీ మరో ఫోటో మీ వద్దే ఉంటుంది.",
  "training.lessons.owner-profile-photos.title": "ప్రొఫైల్ ఫోటోలు మరియు మీ పేరు",
  "training.lessons.owner-profile-photos.step1": "ప్రతి ఒక్కరి ఫోటో యాప్ పైభాగంలో వారి పేరు పక్కన, మీ సిబ్బంది పేజీలో మరియు వారి సందేశాల పక్కన కనిపిస్తుంది. మీరు ఆమోదించే వరకు బృంద సభ్యుడి ఫోటో ఎక్కడా కనిపించదు — ఆమోదం మీది మాత్రమే, మరియు ఎవరూ తమ స్వంత ఫోటోను తామే ఆమోదించలేరు.",
  "training.lessons.owner-profile-photos.step2": "ఎవరైనా ఫోటో పంపినప్పుడు, మీ గంట మోగుతుంది. దాన్ని చూడటానికి సిబ్బంది పేజీని తెరవండి, ఆపై ఆమోదించండి లేదా ఆమోదించవద్దు అని ఎంచుకోండి. మీరు ఆమోదించకపోతే, ఆ వ్యక్తిని మరో ఫోటోను ఎంచుకోమని చెబుతారు.",
  "training.lessons.owner-profile-photos.step3": "ఒక వ్యక్తి తమ ఫోటోను మార్చినట్లయితే, కొత్తది అదే విధంగా మీ ఆమోదం కోసం వేచి ఉంటుంది. అది వేచి ఉన్నప్పుడు వారి ప్రస్తుత ఫోటో అలాగే ఉంటుంది — మరియు మీరు మార్పును ఆమోదించకపోతే అది అలాగే ఉంటుంది.",
  "training.lessons.owner-profile-photos.step4": "మీ స్వంత ఫోటోకు ఆమోదం అవసరం లేదు: దాన్ని సెట్టింగ్‌లలో, మీ ప్రొఫైల్ ఫోటో కింద సెట్ చేయండి. అదే కార్డ్‌లో మీ పేరు కూడా ఉంటుంది — అక్కడ మీరు సెట్ చేసిన పేరు మీ బృందం చూసే ప్రతిచోటా, యాప్‌లో మరియు సందేశాలలో, యజమాని అనే పదాన్ని భర్తీ చేస్తుంది.",
  "payroll.dd.corrected": "సరిదిద్దిన ఫారమ్",
  "payroll.dd.correctedDone": "మీ సరిదిద్దిన వివరాలు యజమానికి పంపబడ్డాయి.",
  "payroll.dd.correctionNotice": "యజమాని మీ ఫారమ్‌ను మీరు సరిదిద్దడానికి మీకు తిరిగి పంపారు. ప్రతి అంకెను తనిఖీ చేసి, సంతకం చేసి, మళ్లీ పంపండి.",
  "payroll.dd.correctionWaiting": "తిరిగి పంపబడింది — వారి సరిదిద్దిన ఫారమ్ కోసం వేచి ఉంది",
  "payroll.dd.fixHelp": "ఒక అంకె తప్పుగా ఉంటే, మీ వివరాలను సరిదిద్ది ఫారమ్‌ను మళ్లీ పంపండి. మీ కొత్త సంతకం చేసిన ఫారమ్ పాతదాని స్థానాన్ని తీసుకుంటుంది, మరియు అది సరిదిద్దబడిందని యజమానికి తెలియజేయబడుతుంది.",
  "payroll.dd.fixMistake": "తప్పును సరిదిద్దండి",
  "payroll.dd.form.historyTitle": "మునుపటి సంతకం చేసిన ఫారమ్‌లు",
  "payroll.dd.form.ownerOnlyNote": "ఈ ఫారమ్‌ను మీరు, యజమాని, మాత్రమే తెరవగలరు. ఇది పూర్తి బ్యాంక్ నంబర్‌లను మరియు సభ్యుని సంతకాన్ని చూపుతుంది.",
  "payroll.dd.form.replacedOn": "{date}న భర్తీ చేయబడింది",
