  "payroll.dd.sendBack": "సరిదిద్దడానికి తిరిగి పంపండి",
  "payroll.dd.sendBackDone": "{name}కు తిరిగి పంపబడింది — ఇప్పుడు వారు తమ వివరాలను సరిదిద్దగలరు.",
  "payroll.dd.signHelp": "మీ పేరు రాయండి, ఆపై మీ సంతకం ఎలా కనిపిస్తుందో ఎంచుకోండి. ఇది మీ ఎలక్ట్రానిక్ సంతకం — ఇది మీ డైరెక్ట్ డిపాజిట్ ఫారమ్‌పై ఇక్కడ చూపినట్లుగానే ఉంచబడుతుంది.",
