  "payroll.profile.name": "పూర్తి పేరు",
  "payroll.profile.noAddress": "ఇంకా ఇంటి చిరునామా ఏదీ నమోదు కాలేదు.",
  "payroll.profile.note": "ఈ వివరాలు మీ వేతన మరియు పన్ను ఫారమ్‌ల కోసం ఉపయోగించబడతాయి, మరియు మీరు మాత్రమే వాటిని ఇక్కడ చూడగలరు. ఏదైనా మార్చాల్సిన అవసరం ఉంటే, యజమానిని లేదా మీ మేనేజర్‌ను అడగండి — వారే వాటిని నవీకరించగలరు.",
