  "training.lessons.owner-dd-setup.step5": "చేరేది సీలు చేసిన, సంతకం చేసిన ఫారమ్: పేరోల్‌లో ఆ వ్యక్తి వరుస నుండి మీరు దానిని తెరిచి పూర్తి నంబర్‌లను చదవవచ్చు, ప్రింట్ చేయవచ్చు లేదా కాపీని సేవ్ చేయవచ్చు — మీరు దానిని ఎప్పటికీ సవరించలేరు. ఒక నంబర్ తప్పుగా అనిపిస్తే, ఫారమ్‌ను తిరిగి పంపండి: ఆ వ్యక్తే దానిని సరిదిద్ది మళ్లీ సంతకం చేస్తారు, వారి సరిదిద్దిన ఫారమ్ పాతదాని స్థానాన్ని తీసుకుంటుంది, మరియు మునుపటి ఫారమ్ దాని భర్తీ తేదీతో రికార్డులో ఉంటుంది.",
  "payroll.profile.ownerNote": "ఇవి ఫైల్‌లో ఉన్న మీ స్వంత వివరాలు, మీ ఖాతా నుండి. మీరు మాత్రమే వాటిని ఇక్కడ చూడగలరు — అవి మీవే కాబట్టి, మారినప్పుడు మీరు వాటిని ఇక్కడే నవీకరించవచ్చు.",
