  "staff.memberDialog.clockAccessHint": "మేనేజర్లకు మాత్రమే — రెండు వేర్వేరు టిక్‌లు. గడియార బోర్డు & తప్పిన క్లాక్-అవుట్‌లు ఈ మేనేజర్‌కు జట్టు గడియార నమోదులను చూడటానికి మరియు సిబ్బంది పేజీ నుండి సమయ నమోదులను సరిచేయడానికి అనుమతిస్తుంది. కాల్-ఇన్‌లు ఈ మేనేజర్‌కు కాల్-ఇన్ విండోలను తెరవడానికి అనుమతిస్తుంది, ఎవరికైనా షిఫ్ట్ షెడ్యూల్ చేయనప్పుడు వారిని పని చేయనివ్వడం. ఈ టిక్‌లు సిబ్బందికి ఏమీ చేయవు.",
