  "workforce.clockGate.closedNext": "ప్రస్తుతం మీకు పని షెడ్యూల్ చేయబడలేదు, మీ కోసం ఏ కాల్-ఇన్ విండో తెరిచి లేదు. మీ తదుపరి షిఫ్ట్ {when} ప్రారంభమవుతుంది.",
