  "staff.callIn.title": "కాల్-ఇన్‌లు & మిస్ అయిన క్లాక్-అవుట్‌లు",
  "staff.callIn.desc": "ఎవరికైనా షిఫ్ట్ షెడ్యూల్ చేయనప్పుడు వారిని పిలవండి, క్లాక్-అవుట్ మర్చిపోయినప్పుడు సమయ నమోదులను సరిచేయండి. కాల్-ఇన్ విండో ఆ వ్యక్తి క్లాక్ అవుట్ చేసే వరకు తెరిచి ఉంటుంది.",
