  "staff.timeFix.open": "సమయాలను సరిచేయండి",
  "apiErrors.clockGate.notScheduled": "ప్రస్తుతం మీకు పని షెడ్యూల్ చేయబడలేదు, మీ కోసం ఏ కాల్-ఇన్ విండో తెరిచి లేదు.",
  "apiErrors.clockAdmin.callinsNotGranted": "యజమాని మాత్రమే, లేదా యజమాని కాల్-ఇన్‌లను నమ్మి అప్పగించిన మేనేజర్ మాత్రమే అది చేయగలరు.",
  "apiErrors.clockAdmin.boardNotGranted": "యజమాని మాత్రమే, లేదా యజమాని గడియార బోర్డు మరియు తప్పిన క్లాక్-అవుట్‌లను నమ్మి అప్పగించిన మేనేజర్ మాత్రమే అది చేయగలరు.",
  "apiErrors.clockAdmin.ownerOnlyForManager": "మేనేజర్ యొక్క కాల్-ఇన్‌లను మరియు సమయ నమోదులను యజమాని మాత్రమే నిర్వహించగలరు.",
  "apiErrors.clockFix.outBeforeIn": "క్లాక్-అవుట్ సమయం క్లాక్-ఇన్ సమయం తర్వాత ఉండాలి.",
  "apiErrors.clockFix.breakOutside": "విరామ సమయాలు క్లాక్-ఇన్ మరియు క్లాక్-అవుట్ సమయాల మధ్య ఉండాలి.",
  "apiErrors.clockFix.invalidTime": "ప్రతి సమయాన్ని చెల్లుబాటు అయ్యే తేదీ మరియు సమయంగా పంపండి.",
  "apiErrors.notFound.timeEntryFound": "సమయ నమోదు కనుగొనబడలేదు.",
  "training.lessons.mgr-clock-callin.title": "కాల్-ఇన్‌లు మరియు గడియార సవరణలు",
  "training.lessons.mgr-clock-callin.step1": "యజమాని ఒక మేనేజర్‌కు రెండు వేర్వేరు టిక్‌లు ఇవ్వవచ్చు. కాల్-ఇన్‌లతో, మీరు ఒక సిబ్బంది సభ్యుని కోసం కాల్-ఇన్ విండోను తెరవవచ్చు, మరియు గడియార బోర్డు & తప్పిన క్లాక్-అవుట్‌లతో, మీరు జట్టు గడియార బోర్డును చూడవచ్చు మరియు సిబ్బంది పేజీ నుండి సమయ నమోదులను సరిచేయవచ్చు. ప్రతి టిక్ దానంతట అదే పని చేస్తుంది — మేనేజర్ ఒకటి లేకుండా మరొకటి కలిగి ఉండవచ్చు.",
  "training.lessons.mgr-clock-callin.step2": "ఏ షిఫ్ట్ కవర్ చేయనప్పుడు కాల్-ఇన్ విండో ఒక వ్యక్తిని సైన్ ఇన్ చేసి క్లాక్ ఇన్ చేయనిస్తుంది. సిబ్బంది పేజీలో, కాల్-ఇన్‌లు & మిస్ అయిన క్లాక్-అవుట్‌ల కార్డ్ నుండి దాన్ని తెరవండి.",
  "training.lessons.mgr-clock-callin.step3": "ఆ వ్యక్తి క్లాక్ అవుట్ చేసే వరకు విండో తెరిచి ఉంటుంది — ఆ తర్వాత సాధారణ 10-నిమిషాల సైన్-అవుట్ గ్రేస్ వస్తుంది — లేదా మీరు లేదా యజమాని దాన్ని ముందుగానే మూసివేసే వరకు. ఏదీ దాన్ని దానంతట అదే మూసివేయదు.",
  "training.lessons.mgr-clock-callin.step4": "ఎవరైనా క్లాక్ అవుట్ చేయడం మర్చిపోతే, షెడ్యూల్ చేసిన షిఫ్ట్ ముగిసిన వెంటనే వారి నమోదు సిబ్బంది పేజీలో మరియు పేరోల్‌లో గుర్తు పెట్టబడుతుంది, మీకు మరియు యజమానికి తెలియజేయబడుతుంది. నమోదు సరిచేసే వరకు లెక్కిస్తూనే ఉంటుంది.",
  "training.lessons.mgr-clock-callin.step5": "సిబ్బంది పేజీ నుండి నమోదును సరిచేయండి: క్లాక్-ఇన్, క్లాక్-అవుట్ మరియు విరామ సమయాలను సెట్ చేయండి. మేనేజర్ సిబ్బంది నమోదులను మాత్రమే సరిచేస్తారు — మేనేజర్ యొక్క స్వంత నమోదులను యజమాని సరిచేస్తారు.",
  "staffLib.perm.staffDocuments": "సిబ్బంది పత్రాలు",
  "staffLib.area.documentsAccess": "సిబ్బంది పత్రాలు",
  "staff.memberDialog.documentsAccessHint": "మేనేజర్లకు మాత్రమే — ఈ టిక్‌తో, ఈ మేనేజర్ సిబ్బంది సభ్యుల పత్ర ఫైళ్లను తెరవగలరు: ప్రతి వ్యక్తి కోసం ఉంచిన కాగితాలు, W-4 ఫారమ్‌లు, ఉద్యోగ దరఖాస్తులు మరియు గుర్తింపు కాపీలు వంటివి. ముందుగా మీ నిర్ధారణ అడుగుతారు — ఈ ఫైళ్లలో సామాజిక భద్రతా సంఖ్యలు మరియు పుట్టిన తేదీలు ఉంటాయి. ఈ టిక్ సిబ్బందికి ఏమీ చేయదు.",
  "staff.documentsWarning.body": "ఈ వ్యక్తి, సామాజిక భద్రతా సంఖ్యలు మరియు పుట్టిన తేదీలతో సహా, మీ సిబ్బంది సభ్యుల గురించిన గోప్య సమాచారాన్ని చూడగలరు.",
  "staff.documentsWarning.confirm": "అవును, నాకు అర్థమైంది",
  "staff.documents.title": "సిబ్బంది పత్రాలు",
  "staff.documents.desc": "ప్రతి వ్యక్తి కోసం మీరు ఉంచే కాగితాలు — W-4 ఫారమ్‌లు, ఉద్యోగ దరఖాస్తులు, పన్ను ఫారమ్‌లు, గుర్తింపు కాపీలు. మీరు, మరియు మీరు సిబ్బంది పత్రాల టిక్ ఇచ్చే మేనేజర్ మాత్రమే ఈ ఫైళ్లను తెరవగలరు.",
  "staff.documents.open": "పత్రాలు",
