  "restaurant.emptyBody": "మీ మొదటి వంటకాన్ని రాయండి — సాస్, డిష్, స్టాక్‌లో ఉన్నదానితో మీరు చేసే ఏదైనా — మరియు దానిని అమ్మడానికి సిద్ధంగా ఉన్నప్పుడు ఉత్పత్తికి లింక్ చేయండి.",
