  "exportsLib.restaurantLedger.title": "రెస్టారెంట్ లెడ్జర్",
  "exportsLib.restaurantLedger.description": "అందుకున్న కొనుగోళ్లు, వ్యర్థాలు, సిబ్బంది భోజనాలు మరియు వంటకం తగ్గుదల ఒకే లెడ్జర్‌లో: విభాగం, తేదీ, వస్తువు, పరిమాణం, యూనిట్ ఖర్చు, మొత్తం ఖర్చు మరియు సూచన.",
  "print.labelReceived": "అందుకున్నది",
