  "storefronts.ebayDesc": "మీ eBay స్టోర్‌ఫ్రంట్‌ను ఒకసారి కనెక్ట్ చేయండి. eBayలో ఒక వస్తువు అమ్ముడైనప్పుడు, దాని సంఖ్య ఇక్కడ వాటంతట అదే తగ్గుతుంది, అమ్మకం మీ కదలికలలో నమోదు అవుతుంది — అది స్కాన్ చేసి బయటకు తీసినట్లే. అమ్మకాలు ఒక దిశలో మాత్రమే ప్రవహిస్తాయి: eBay నుండి యాప్‌లోకి.",
