  "storefronts.matchingIntro": "{count} అమ్ముడైన వస్తువు(లను) ఇంకా ఉత్పత్తితో సరిపోల్చలేకపోయారు. ప్రతిదాన్ని దాని ఉత్పత్తికి లింక్ చేయండి మరియు దాని నిలిపివేసిన అమ్మకాలు వాటంతట అవే నమోదు అవుతాయి — అది వేచి ఉన్నప్పుడు ఏదీ పోదు.",
