  "storefronts.notAvailableBody": "యాప్ యజమాని ఇంకా eBay కీలను జోడించలేదు, కాబట్టి ఈ ద్వారం తెరవలేరు. ఈ పేజీలోని మిగతావన్నీ సిద్ధంగా ఉన్నాయి — కీలు వచ్చిన తర్వాత మళ్లీ చూడండి.",
