  "storefronts.title": "స్టోర్‌ఫ్రంట్ కనెక్షన్‌లు",
  "training.lessons.owner-ebay-connect.step1": "స్టోర్‌ఫ్రంట్ కనెక్షన్‌లను (అమ్మకాల సమూహంలో) తెరిచి eBayని కనెక్ట్ చేయండి నొక్కండి. మీరు eBay సొంత పేజీలో సైన్ ఇన్ చేస్తారు — యాప్ మీ eBay పాస్‌వర్డ్‌ను ఎప్పుడూ చూడదు.",
  "training.lessons.owner-ebay-connect.step2": "ఒక eBay స్టోర్‌ఫ్రంట్ ఒక వ్యాపారానికి కనెక్ట్ అవుతుంది — ఆ దుకాణం అమ్మే వస్తువులు ఉన్న వ్యాపారం. మీరు ఒకటి కంటే ఎక్కువ వ్యాపారాలు నడిపితే, ప్రతి దుకాణాన్ని దాని సొంత వ్యాపారానికి కనెక్ట్ చేయండి.",
  "training.lessons.owner-ebay-connect.step3": "మీ eBay స్టాక్ ఉన్న స్థానాన్ని ఎంచుకోండి, తద్వారా అమ్మకాలు సరైన షెల్ఫ్ నుండి తీసివేయబడతాయి.",
  "training.lessons.owner-ebay-connect.step4": "అప్పటి నుండి, అమ్మకాలు వాటంతట అవే వస్తాయి: eBayలో ఒక వస్తువు అమ్ముడైనప్పుడు, దాని సంఖ్య ఇక్కడ తగ్గుతుంది మరియు అమ్మకం eBay ఆర్డర్ నంబర్‌తో కదలికలలో నమోదు అవుతుంది. ఏదీ వెనక్కి వెళ్లదు — యాప్ మీ eBay జాబితాలను ఎప్పుడూ మార్చదు.",
  "training.lessons.owner-ebay-connect.step5": "అమ్మకం జాబితాలోని SKU, UPC లేదా ISBN ద్వారా సరిపోలుతుంది — ఈ మూడింటిలో జాబితాలో ఏది ఉంటే దాని ద్వారా. అమ్మకం సరిపోలకపోతే, అది స్టోర్‌ఫ్రంట్ కనెక్షన్‌ల పేజీలో 'సరిపోల్చడం అవసరమైన అమ్మకాలు' కింద వేచి ఉంటుంది: దానిని ఒకసారి దాని ఉత్పత్తికి లింక్ చేయండి, ఆ అమ్మకం — మరియు భవిష్యత్తులో అలాంటివి — వాటంతట అవే నమోదు అవుతాయి. 'ఇప్పుడు అమ్మకాల కోసం తనిఖీ చేయండి' ఇటీవలివన్నీ తెస్తుంది, మరియు డిస్‌కనెక్ట్ చేయడం కనెక్షన్‌ను ఆపుతుంది; ఇప్పటికే నమోదైన అమ్మకాలు ఉంటాయి.",
  "training.lessons.owner-ebay-connect.title": "మీ eBay దుకాణాన్ని కనెక్ట్ చేయండి",
